# Essential imports (guaranteed to be available)
import os
import torch
import torch.nn as nn
import torch.nn.functional as F
import torch.optim as optim
from data_loader import build_train_val_dataloaders
import json
from tqdm import tqdm
import numpy as np
from sklearn.metrics import roc_auc_score

import timm

# 1. Setup
NUM_SPECIES = 206
DATA_DIR = "/mnt/disks/data/birdclef"
METADATA_FILE = os.path.join(DATA_DIR, "train.csv")

# 2. Data Loaders
iteration_number = int(os.environ.get("ITERATION_NUMBER", 0))
batch_size_options = [64, 128, 256]
lr_options = [0.001, 0.0001, 0.00001]
dropout_rate = [0.0, 0.2, 0.5]

batch_size = batch_size_options[iteration_number % 3]
learning_rate = lr_options[iteration_number % 3]
dropout = dropout_rate[(iteration_number // 3) % len(dropout_rate)]

train_loader, val_loader = build_train_val_dataloaders(
    batch_size=batch_size,
    augment=True,
    val_split=0.2
)

device = torch.device("cuda" if torch.cuda.is_available() else "cpu")

# 3. Model Architecture (Transfer Learning)
class BirdCLEFModel(nn.Module):
    def __init__(self, num_classes):
        super().__init__()
        self.base_model = timm.create_model("efficientnet_b0", pretrained=True, in_chans=1, num_classes=0)
        # Freeze base model
        for param in self.base_model.parameters():
            param.requires_grad = False
            
        self.classifier = nn.Sequential(
            nn.Linear(self.base_model.num_features, 256),
            nn.ReLU(),
            nn.Dropout(dropout),
            nn.Linear(256, num_classes)
        )
        
    def forward(self, x):
        features = self.base_model(x)
        logits = self.classifier(features)
        return logits

model = BirdCLEFModel(num_classes=NUM_SPECIES).to(device)

# 4. Optimizer, Loss, and AMP Scaler
criterion = nn.BCEWithLogitsLoss()
optimizer = optim.Adam(model.classifier.parameters(), lr=learning_rate)
scaler = torch.amp.GradScaler("cuda")

# Training Loop
max_epochs = 20
train_losses = []

for epoch in range(max_epochs):
    model.train()
    epoch_loss = 0.0
    for inputs, labels in tqdm(train_loader, desc=f"Epoch {epoch+1}/{max_epochs}"):
        inputs, labels = inputs.to(device), labels.to(device)
        
        optimizer.zero_grad()
        
        with torch.amp.autocast("cuda"):
            outputs = model(inputs)
            loss = criterion(outputs, labels.float())
        
        scaler.scale(loss).backward()
        scaler.step(optimizer)
        scaler.update()
        
        epoch_loss += loss.item() * inputs.size(0)
    
    epoch_loss /= len(train_loader.dataset)
    train_losses.append(epoch_loss)
    print(f"Epoch {epoch+1}/{max_epochs}, Loss: {epoch_loss:.4f}")

# Validation Loop
model.eval()
all_preds = []
all_labels = []

with torch.no_grad():
    for inputs, labels in tqdm(val_loader, desc="Validation"):
        inputs, labels = inputs.to(device), labels.to(device)
        
        with torch.amp.autocast("cuda"):
            outputs = model(inputs)
            preds = torch.sigmoid(outputs).cpu().numpy()
        
        all_preds.extend(preds)
        all_labels.extend(labels.cpu().numpy())

all_labels = np.stack(all_labels)
all_preds = np.array(all_preds)

# Calculate Validation AUC
try:
    final_auc = roc_auc_score(all_labels, all_preds, multi_class='ovr')
except ValueError as e:
    print(f"Error calculating AUC: {e}")
    final_auc = 0.0

print(f"Final Validation AUC: {final_auc:.4f}")

# Save Metrics
metrics = {
    "final_train_loss": train_losses[-1],
    "final_auc": final_auc,
    "num_params": sum(p.numel() for p in model.parameters()),
    "epochs_trained": max_epochs,
    "batch_size": batch_size,
    "training_samples": len(train_loader.dataset),
    "eval_samples": len(val_loader.dataset)
}

with open("metrics.json", "w") as f:
    json.dump(metrics, f)

print(f"METRICS: {json.dumps(metrics)}")

# Save Model
torch.save(model.state_dict(), "model.pt")